// Concatenates the numbered migrations into supabase/migrations/ALL.sql, so the
// whole schema can be applied in one paste. Every migration is idempotent, so
// the bundle is safe on a fresh database or a partly-migrated one.
//
// Run: node scripts/build-migration-bundle.mjs

import { readFileSync, writeFileSync, readdirSync } from "node:fs";

const dir = new URL("../supabase/migrations/", import.meta.url);
const files = readdirSync(dir)
  .filter((f) => /^\d{4}_.*\.sql$/.test(f))
  .sort();

// 0001-0004 predate this bundle and are assumed applied.
const bundled = files.filter((f) => Number(f.slice(0, 4)) >= 5);

const header = `-- ============================================================================
-- Wingman — complete schema, migrations ${bundled[0].slice(0, 4)} → ${bundled.at(-1).slice(0, 4)}
--
-- Generated by scripts/build-migration-bundle.mjs. Do not edit by hand: edit
-- the numbered files in supabase/migrations/ and regenerate.
--
-- Every statement is idempotent, so this is safe to run on a fresh database or
-- on one that already has some of it. Run it as one paste, top to bottom.
--
-- Assumes 0001-0004 are already applied (social layer, threaded posts,
-- reactions/attempts/completions, progress merge).
-- ============================================================================

`;

const body = bundled
  .map((f) => {
    const sql = readFileSync(new URL(f, dir), "utf8").trimEnd();
    const rule = "-".repeat(76);
    return `-- ${"#".repeat(76)}\n-- ${f}\n-- ${"#".repeat(76)}\n\n${sql}\n`;
  })
  .join("\n\n");

writeFileSync(new URL("ALL.sql", dir), header + body);
console.log(`bundled ${bundled.length} migrations -> supabase/migrations/ALL.sql`);
console.log(bundled.map((f) => "  " + f).join("\n"));
